package com.smartcoms.hms.config;
import com.smartcoms.hms.entity.*; import com.smartcoms.hms.repository.*; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.*; import java.time.*;
@Configuration class DataInitializer { @Bean CommandLineRunner load(PatientRepository patients,BedRepository beds,AppointmentRepository appointments){return a->{ if(patients.count()==0){ seedPatient(patients,"Aarav Mehta","M","A+","Cardiology","Hypertension"); seedPatient(patients,"Priya Sharma","F","O+","Neurology","Migraine"); seedPatient(patients,"Rohan Gupta","M","B+","Orthopedics","Knee pain"); for(int i=1;i<=42;i++){Bed b=new Bed();b.setBedNumber("B-"+String.format("%03d",i));b.setWard(i<7?"Critical Care":"General Ward");b.setCategory(i<7?"ICU":"General");b.setStatus(i%4==0?"Occupied":"Available");beds.save(b);} for(int i=0;i<5;i++){Appointment ap=new Appointment();ap.setPatientName(new String[]{"Maya Thomas","Vikram Rao","Anaya Singh","Kabir Khan","Sara Ali"}[i]);ap.setDoctor("Dr. "+new String[]{"N. Iyer","A. Kapoor","R. Sen","P. Shah","M. Bose"}[i]);ap.setDepartment(new String[]{"Cardiology","Neurology","Pediatrics","Orthopedics","Dermatology"}[i]);ap.setDate(LocalDate.now());ap.setTime(LocalTime.of(9+i,30));appointments.save(ap);}}};} void seedPatient(PatientRepository r,String n,String g,String bg,String d,String dx){Patient p=new Patient();p.setPatientCode("CA-"+(1000+r.count()+1));p.setFullName(n);p.setGender(g);p.setBloodGroup(bg);p.setDepartment(d);p.setDiagnosis(dx);p.setPhone("9876543210");p.setDateOfBirth(LocalDate.of(1987,1,1));r.save(p);} }
